/**
 * The Worker entry: OpenNext's generated handler, behind one guard.
 *
 * phive.ivqonsanada.com sits on a domain whose old server was hacked into serving
 * gambling spam to search bots at /?go=<keyword> and a fake /sitemaps.xml. Answering
 * those with 410 Gone gets them dropped from search results faster than rendering
 * the home page would.
 */
// The import is missing before the first build and untyped after it, so neither
// state can satisfy @ts-expect-error.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

const worker = {
  async fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> {
    const url = new URL(request.url);
    if (url.searchParams.has("go") || url.pathname === "/sitemaps.xml") {
      return new Response("Gone", {
        status: 410,
        headers: { "content-type": "text/plain", "x-robots-tag": "noindex" },
      });
    }
    return handler.fetch(request, env, ctx);
  },
};

export default worker;
